trait Notifier[A]: def notify(a: A, msg: String): Unit

final class LegacySms(val phone: String):
  def send(msg: String): Unit = println(s"$phone: $msg")

given Notifier[LegacySms] with                       // the adapter
  def notify(sms: LegacySms, msg: String): Unit = sms.send(msg)

def sendAll[A](xs: List[A], msg: String)(using n: Notifier[A]): Unit =
  xs.foreach(n.notify(_, msg))                       // client sees Notifier only

