import scala.language.implicitConversions

trait PaymentGateway { def charge(amount: Long): String }
final class LegacyCharge {
  def createCharge(amount: Long, currency: String): String = s"$amount $currency"
}

object Adapters {
  implicit def legacyToGateway(l: LegacyCharge): PaymentGateway =
    new PaymentGateway {
      def charge(amount: Long): String = l.createCharge(amount, "USD")
    }
}

object Client {
  import Adapters._
  val legacyCharge = new LegacyCharge
  val gateway: PaymentGateway = legacyCharge   // conversion applied silently
}
